import React, { useState } from 'react';
// import './EnquiryForm.css';

const EnquiryForm = () => {
    const [name, setName] = useState('');
    const [email, setEmail] = useState('');
    const [mobile, setMobile] = useState('');
    const [city, setCity] = useState('');
    const [option, setOption] = useState('');
    const [query, setQuery] = useState('');

    const handleNameChange = (e) => {
        setName(e.target.value);
    };

    const handleEmailChange = (e) => {
        setEmail(e.target.value);
    };

    const handleMobileChange = (e) => {
        setMobile(e.target.value);
    };

    const handleCityChange = (e) => {
        setCity(e.target.value);
    };

    const handleOptionChange = (e) => {
        setOption(e.target.value);
    };

    const handleQueryChange = (e) => {
        setQuery(e.target.value);
    };

    const handleSubmit = (e) => {
        e.preventDefault();

        console.log('Form submitted:', { name, email, mobile, city, option, query });

        setName('');
        setEmail('');
        setMobile('');
        setCity('');
        setOption('');
        setQuery('');
    };

    return (
        <div className='w-[300px] md:w-[450px] py-10 rounded-xl bg-indigo-40 bg-black bg-opacity-60'>
            <form className="flex flex-col items-center justify-items-center space-y-7 " onSubmit={handleSubmit}>

                <div className="flex flex-col space-y-2 w-[250px] md:w-[400px]">
                    <label className='text-white'>Full Name <span>*</span></label>
                    <input className={`px-2 sm:px-5 py-1 sm:py-2 text-black text-md rounded-lg sm:rounded-xl outline-0 placeholder-gray-400 placeholder:italic placeholder:text-sm`} type="text" value={name} onChange={handleNameChange} placeholder='Enter Your Name' required />
                </div>

                <div className="flex flex-col space-y-2 ">
                    <label className='text-white'>Email <span>*</span></label>
                    <input className={`px-2 sm:px-5 py-1 sm:py-2 w-[250px] md:w-[400px] text-black text-md rounded-lg sm:rounded-xl outline-0 placeholder-gray-400 placeholder:italic placeholder:text-sm`} type="email" value={email} onChange={handleEmailChange} placeholder='Your Email' required />
                </div>

                <div className="flex flex-col space-y-2 ">
                    <label className='text-white'>Mobile Number <span>*</span></label>
                    <input className={`px-2 sm:px-5 py-1 sm:py-2 w-[250px] md:w-[400px] text-black text-md rounded-lg sm:rounded-xl outline-0 placeholder-gray-400 placeholder:italic placeholder:text-sm`} type="tel" value={mobile} onChange={handleMobileChange} placeholder='Your Mobile number' required />
                </div>

                <div className="flex flex-col space-y-2 ">
                    <label className='text-white'>City <span>*</span></label>
                    <input className={`px-2 sm:px-5 py-1 sm:py-2 w-[250px] md:w-[400px] text-black text-md rounded-lg sm:rounded-xl outline-0 placeholder-gray-400 placeholder:italic placeholder:text-sm`} type="text" value={city} onChange={handleCityChange} placeholder='Your City' required />
                </div>

                {/* <div className="flex flex-col space-y-2">
                    <label>Category <span>*</span></label>
                    <select value={option} onChange={handleOptionChange} required>
                        <option value="">Select an option</option>
                        <option value="foundation">Foundation</option>
                        <option value="boards">Boards</option>
                        <option value="jee">JEE</option>
                        <option value="neet">NEET</option>
                        <option value="target">Target</option>
                    </select>
                </div> */}

                {/* <div className="flex flex-col space-y-2 ">
                    <label className='text-white'>Query <span>*</span></label>
                    <textarea value={query} onChange={handleQueryChange} placeholder='Your Message' required />
                </div> */}

                <button type='submit' className='p-2 bg-indigo-500 text-white rounded-lg hover:scale-105 duration-300'>
                    Submit
                </button>

            </form>
        </div>
    );
};

export default EnquiryForm;
